claims.text:
Addressed visible stage operands and labels: z=Σai·vi · readi=ReLU(vi·z) | three directions 120° apart | active amplitudes1 · inactive0. Controls: One, Two, Three, Reset. Changed computed rows: input amplitudes=1/0/0 / Σa·v=(1,0) / ReLU dot readout=1/0/0 / amplitude SSE=0 · 3 directions in2D | input amplitudes=1/1/0 / Σa·v=(0.5,0.866) / ReLU dot readout=0.5/0.5/0 / amplitude SSE=0.5 · 3 directions in2D | input amplitudes=1/1/1 / Σa·v=(0,0) / ReLU dot readout=0/0/0 / amplitude SSE=3 · 3 directions in2D. Retained computed witnesses: 1 active: read=1/0/0 | 2 active: read=0.5/0.5/0 | 3 active: read=0/0/0. Numeric display is rounded to three decimals unless explicitly shown otherwise; source computations retain full precision. Exact expressions: // Bounded owner construction; no external model or shared runtime engine.
export const sum=(a:number[])=>a.reduce((s,x)=>s+x,0);
export const dot=(a:number[],b:number[])=>sum(a.map((x,i)=>x*b[i]));
export const f=(x:number)=>Number.isFinite(x)?String(Number(x.toFixed(3))):'∞';
export function compute(mode:number){
const V=[[1,0],[-.5,Math.sqrt(3)/2],[-.5,-Math.sqrt(3)/2]],a=[1,mode>=1?1:0,mode>=2?1:0],z=[0,1].map(j=>sum(a.map((v,i)=>v*V[i][j]))),read=V.map(v=>Math.max(0,dot(v,z))),error=sum(a.map((v,i)=>(v-read[i])**2));return{values:[...z,...read,error],rows:[`input amplitudes=${a.join('/')}`,`Σa·v=(${z.map(f).join(',')})`,`ReLU dot readout=${read.map(f).join('/')}`,`amplitude SSE=${f(error)} · 3 directions in2D`],receipt:`${mode+1} active: read=${read.map(f).join('/')}`};
}
